export async function execute(args = {}) {
  const v = (args.values || []).map(Number).filter((x) => !Number.isNaN(x))
  if (!v.length) return { count: 0 }
  return { count: v.length, mean: v.reduce((a, b) => a + b, 0) / v.length, min: Math.min(...v), max: Math.max(...v) }
}

import test from 'node:test'
import assert from 'node:assert'
import { execute } from '../lib/impl.js'
test('stats', async () => {
  const r = await execute({ values: [1, 2, 3] })
  assert.equal(r.mean, 2); assert.equal(r.min, 1); assert.equal(r.max, 3)
})
